/* @autogenerated */
import { CommonModule } from '@angular/common';
import { Component, computed, effect, OnDestroy, OnInit, signal } from '@angular/core';
import { FormControl, FormGroup, ReactiveFormsModule } from '@angular/forms';
import { MatFormFieldModule } from '@angular/material/form-field';
import { MatInputModule } from '@angular/material/input';
import { MatIconModule } from '@angular/material/icon';
import { TranslocoModule } from '@jsverse/transloco';
import { Subscription } from 'rxjs';
import { BaseEditable } from '../base-editable';
import { EditableHiddenMarkComponent } from '../editable-hidden-mark/editable-hidden-mark.component';
import { SubFormEditable } from '../subform-editable';

export interface CreditCard {
  number: string;
  holder: string;
  expiry: string;
  cvv: string;
}

type CardNetwork = 'visa' | 'mastercard' | 'amex' | 'discover' | 'unknown';

const NETWORK_PATTERNS: { network: CardNetwork; pattern: RegExp; length: number[]; cvvLength: number }[] = [
  { network: 'amex', pattern: /^3[47]/, length: [15], cvvLength: 4 },
  { network: 'mastercard', pattern: /^5[1-5]|^2[2-7]/, length: [16], cvvLength: 3 },
  { network: 'discover', pattern: /^6(?:011|22[1-9]|4[4-9]|5)/, length: [16], cvvLength: 3 },
  { network: 'visa', pattern: /^4/, length: [13, 16, 19], cvvLength: 3 },
];

function detectNetwork(number: string): CardNetwork {
  const raw = number.replace(/\s/g, '');
  return NETWORK_PATTERNS.find((n) => n.pattern.test(raw))?.network ?? 'unknown';
}

function luhn(number: string): boolean {
  const digits = number.replace(/\D/g, '').split('').map(Number).reverse();
  const sum = digits.reduce((acc, d, i) => {
    if (i % 2 !== 0) {
      d *= 2;
      if (d > 9) d -= 9;
    }
    return acc + d;
  }, 0);
  return sum % 10 === 0;
}

function formatNumber(raw: string, network: CardNetwork): string {
  const digits = raw.replace(/\D/g, '');
  if (network === 'amex') {
    return [digits.slice(0, 4), digits.slice(4, 10), digits.slice(10, 15)].filter(Boolean).join(' ');
  }
  return digits.match(/.{1,4}/g)?.join(' ') ?? digits;
}

const NETWORK_ICONS: Record<CardNetwork, string> = {
  visa: 'credit_card',
  mastercard: 'credit_card',
  amex: 'credit_card',
  discover: 'credit_card',
  unknown: 'credit_card',
};

@Component({
  selector: 'editable-credit-card',
  standalone: true,
  imports: [
    CommonModule,
    ReactiveFormsModule,
    MatFormFieldModule,
    MatInputModule,
    MatIconModule,
    TranslocoModule,
    EditableHiddenMarkComponent,
  ],
  providers: BaseEditable.getValidableAccessorProvider(EditableCreditCardComponent),
  templateUrl: './editable-credit-card.component.html',
  styleUrls: ['./editable-credit-card.component.scss'],
})
export class EditableCreditCardComponent extends SubFormEditable<CreditCard> implements OnInit, OnDestroy {
  network = signal<CardNetwork>('unknown');
  showCvv = signal(false);
  flipped = signal(false);

  networkIcon = computed(() => NETWORK_ICONS[this.network()]);
  maxNumberLength = computed(() => (this.network() === 'amex' ? 19 : 23)); // with spaces
  cvvLength = computed(() => (this.network() === 'amex' ? 4 : 3));

  private subs = new Subscription();

  constructor() {
    super(
      new FormGroup({
        number: new FormControl<string>('', { nonNullable: true }),
        holder: new FormControl<string>('', { nonNullable: true }),
        expiry: new FormControl<string>('', { nonNullable: true }),
        cvv: new FormControl<string>('', { nonNullable: true }),
      }),
    );
    this.defaultValues = () => ({ number: '', holder: '', expiry: '', cvv: '' });
  }

  override ngOnInit(): void {
    super.ngOnInit();

    this.subs.add(
      this.form.get('number')!.valueChanges.subscribe((raw: string) => {
        const net = detectNetwork(raw);
        this.network.set(net);
        const formatted = formatNumber(raw, net);
        if (formatted !== raw) {
          this.form.get('number')!.patchValue(formatted, { emitEvent: false });
        }
      }),
    );

    this.subs.add(
      this.form.get('expiry')!.valueChanges.subscribe((raw: string) => {
        const digits = raw.replace(/\D/g, '');
        let formatted = digits;
        if (digits.length >= 3) {
          formatted = digits.slice(0, 2) + '/' + digits.slice(2, 4);
        }
        if (formatted !== raw) {
          this.form.get('expiry')!.patchValue(formatted, { emitEvent: false });
        }
      }),
    );
  }

  override ngOnDestroy(): void {
    this.subs.unsubscribe();
    super.ngOnDestroy();
  }

  onNumberKeydown(event: KeyboardEvent): void {
    const allowed = /[\d\s\t]|Backspace|Delete|ArrowLeft|ArrowRight|Tab/;
    if (!allowed.test(event.key) && !event.ctrlKey && !event.metaKey) {
      event.preventDefault();
    }
  }

  onExpiryKeydown(event: KeyboardEvent): void {
    const allowed = /[\d/]|Backspace|Delete|ArrowLeft|ArrowRight|Tab/;
    if (!allowed.test(event.key) && !event.ctrlKey && !event.metaKey) {
      event.preventDefault();
    }
  }

  override validate(_: any) {
    const { number, holder, expiry, cvv } = this.form.getRawValue();
    const raw = number.replace(/\s/g, '');
    const errs: Record<string, boolean> = {};

    if (raw) {
      const netDef = NETWORK_PATTERNS.find((n) => n.network === this.network());
      if (netDef && !netDef.length.includes(raw.length)) {
        errs['cardInvalidLength'] = true;
      } else if (raw.length >= 13 && !luhn(raw)) {
        errs['cardLuhnFailed'] = true;
      }
    }

    if (expiry) {
      const [mm, yy] = expiry.split('/').map(Number);
      if (!mm || !yy || mm < 1 || mm > 12) {
        errs['cardExpiryFormat'] = true;
      } else {
        const now = new Date();
        const exp = new Date(2000 + yy, mm - 1, 1);
        if (exp < new Date(now.getFullYear(), now.getMonth(), 1)) {
          errs['cardExpired'] = true;
        }
      }
    }

    if (cvv && cvv.length !== this.cvvLength()) {
      errs['cardCvvLength'] = true;
    }

    return Object.keys(errs).length > 0 ? errs : null;
  }
}
